select 
from t_r_data_perm_user_bundle_grant g
left join t_r_data_perm_bundle r on r.id = g.bundle_id
where g.user_id = #{userId}
  and g.effective_time <= #{asOf}
  and (g.expiration_time is null or g.expiration_time > #{asOf})

select 
from t_r_data_perm_user_bundle_grant
where user_id in
#{uid}
  and effective_time <= #{asOf}
  and (expiration_time is null or expiration_time > #{asOf})

select bundle_id as bundleId, count(distinct user_id) as cnt from t_r_data_perm_user_bundle_grant where effective_time <= #{asOf} and (expiration_time is null or expiration_time > #{asOf}) and bundle_id in
#{rid}
group by bundle_id

